---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Context meter: How full the context is and what fills it, with Compact to free room.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change context-meter.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './context-meter.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="context-meter" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="ctm" data-open="1">
  <button class="ctm-tg" aria-expanded="true" aria-label="Context"><span class="ctm-ring" aria-hidden="true"><svg viewBox="0 0 20 20"><circle class="tr" cx="10" cy="10" r="7.5"/><circle class="fl" cx="10" cy="10" r="7.5" pathLength="100"/></svg></span><span><span class="ctm-pc num">0%</span> of context used</span><svg class="i xs"><use href="#i-chev-d"/></svg></button>
  <div class="ctm-pop panel" role="region" aria-label="What fills the context">
    <div class="ctm-ph"><span>In context</span><span class="num"><b class="ctm-tot">0k</b> of 200k tokens</span></div>
    <div class="ctm-bar" aria-hidden="true"></div>
    <div class="ctm-leg"></div>
    <div class="ctm-msg" aria-live="polite"><span></span></div>
    <div class="ctm-f"><span class="ctm-hint">Summarises older turns</span><button class="pill soft sm ctm-go">Compact</button></div>
  </div>
</div>
  </Fragment></div>
</div>
<script>
  import './context-meter.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Context meter ---------- */
/* a pill with the ring opens what fills the context: one bar split by kind, a legend whose rows list their items, and Compact */
/* it never anchors the page's scroll, so the page can't follow it as it changes; on a card it sits in the middle of its room */
.ctm{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:var(--dm-s-2);width:100%;max-width:340px;margin-inline:auto;overflow-anchor:none}
.stage-in:has(>.ctm){overflow-anchor:none}
.stage-in>.ctm{min-height:inherit}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.ctm :is(.pill,.ib,.ctm-tg):active{transform:none}
.ctm-tg{display:inline-flex;align-items:center;gap:var(--dm-s-2);height:32px;padding:0 10px 0 7px;border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);background:var(--dm-surface);box-shadow:var(--dm-shadow);transition:box-shadow var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.ctm-tg:hover{box-shadow:var(--dm-shadow-pop)}}
.ctm-tg .ctm-pc{color:var(--dm-fg);font-weight:500}
.ctm-tg>svg:last-child{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.ctm[data-open="0"] .ctm-tg>svg:last-child{transform:rotate(-90deg)}
/* shut, the panel folds away to nothing (owner, 17 Nov: no room kept for a later state): its height eases to 0 as it fades,
   so the meter shrinks with it and stays centred in its stage, and opens back the same way. Where the browser can't ease a
   height to auto, it opens and shuts at once. It only fades as its height eases, with no glide on top (owner, 19 Nov). Its
   content sits 16px in from every edge (owner, 18 Nov) */
.ctm{interpolate-size:allow-keywords}
.ctm-pop{width:100%;min-height:0;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3);overflow:clip;transition:opacity .32s var(--dm-ease),transform .42s var(--dm-ease),height .42s var(--dm-ease),margin-top .42s var(--dm-ease),padding .42s var(--dm-ease),visibility 0s}
.ctm[data-open="0"] .ctm-pop{height:0;margin-top:calc(-1 * var(--dm-s-2));padding-block:0;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .16s var(--dm-ease),transform .32s var(--dm-ease),height .32s var(--dm-ease),margin-top .32s var(--dm-ease),padding .32s var(--dm-ease),visibility 0s .32s}
@media (prefers-reduced-motion:reduce){.ctm-pop,.ctm[data-open="0"] .ctm-pop{transition:none}}
.ctm-ph{display:flex;align-items:baseline;justify-content:space-between;gap:var(--dm-s-3);font-size:13px;line-height:18px;color:var(--dm-muted)}
.ctm-ph b{color:var(--dm-fg);font-weight:500}
/* the bar: one part per kind in the chart palette (the accent first, a neutral grey for the quiet part), on the neutral rail */
.ctm-bar{display:flex;gap:2px;height:8px;border-radius:var(--dm-r-xs);background:var(--dm-rail);overflow:hidden}
.ctm-bar i{height:100%;width:0;flex:none;background:var(--dm-c);transition:width .42s var(--dm-ease),opacity .16s}
.ctm-bar.hl i:not(.on){opacity:.25}
/* the legend's rows answer the pointer: the swatch sits on the content's edge and the hover reaches out round it */
.ctm-leg{display:flex;flex-direction:column;margin:0 -6px}
.ctm-l{display:flex;align-items:center;gap:var(--dm-s-2);padding:5px 6px;border-radius:var(--dm-r-sm);font-size:13px;line-height:18px;color:var(--dm-fg2);cursor:default;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.ctm-l:hover{background:color-mix(in srgb,var(--dm-fg) 5%,transparent)}}
/* the swatch is centred in a 16px column, the column of the message's sign and tick below, so their words line up */
.ctm-l .sw{width:8px;height:8px;margin:0 4px;border-radius:var(--dm-r-tiny,2px);flex:none;background:var(--dm-c)}
.ctm-l .v{margin-left:auto;color:var(--dm-fg)}
/* the message takes no room until it has something to say (owner, 17 Nov), and opens smoothly when it does. A warning is a
   warning notice (owner, 18 Nov): a faint warning tint, the filled warning sign in the warning mark and the words in the text
   colour; the action that resolves it is Compact, below, in the warning tint while it shows. A result is a plain line with
   the green tick */
.ctm-msg{display:grid;grid-template-rows:0fr;margin-top:calc(-1 * var(--dm-s-3));font-size:13px;line-height:18px;color:var(--dm-fg);opacity:0;transition:grid-template-rows .32s var(--dm-ease),margin .32s var(--dm-ease),opacity .24s var(--dm-ease)}
.ctm-msg.on{grid-template-rows:1fr;margin-top:0;opacity:1}
.ctm-msg>span{display:flex;align-items:flex-start;gap:var(--dm-s-2);min-height:0;overflow:hidden}
.ctm-msg>span>svg,.ctm-msg>span>svg.i{flex:none;width:16px;height:16px;margin-top:1px}
/* the notice reaches out as far as the legend's hover, with the legend's padding, so its sign sits in the swatches' column
   and its words on the legend's words */
.ctm-msg.warn>span{margin:0 -6px;padding:8px 6px;border-radius:var(--dm-r-sm);background:color-mix(in srgb,var(--dm-warn-bg) 45%,transparent)}
.ctm-wi{overflow:visible}
.ctm-wi .a{fill:var(--dm-warn-mark);stroke:var(--dm-warn-mark);stroke-width:2;stroke-linejoin:round}
.ctm-wi .b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.ctm-msg.ok>span>svg{color:var(--dm-ok-mark)}
@media (prefers-reduced-motion:reduce){.ctm-msg{transition:none}}
.ctm-f{display:flex;align-items:center;gap:10px;padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ctm-go{overflow:hidden;white-space:nowrap;justify-content:flex-start}
/* while it compacts nothing can be pressed, so it says so where the button was (owner, 21 Nov: "should this be gray button?
   especially the loading animation?"): the spinner in the accent and the words in the loader's sweep, as plain words, the row
   keeping its height and its right edge; Undo comes in once it is done */
.ctm-run{display:inline-flex;align-items:center;gap:6px;height:28px;flex:none;font-size:12.5px;color:var(--dm-fg);white-space:nowrap}
.ctm-run[hidden]{display:none}
.ctm-run .spin{width:12px;height:12px;color:var(--dm-accent-mark,var(--dm-accent))}
.ctm-f .ctm-hint{flex:1;min-width:0;font-size:13px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* the ring: inside the meter's pill, and as its own button where Agent harness puts it in the composer. Its track is the
   neutral rail and its fill the accent's mark colour (3:1), the warning mark near the limit */
.ctm-ft{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px;color:var(--dm-fg2)}
.ctm-ring{width:30px;height:30px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;flex:none;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.ctm-ring:hover{background:var(--dm-row)}}
.ctm-tg .ctm-ring{width:20px;height:20px;background:none}
.ctm-ring svg{width:18px;height:18px;transform:rotate(-90deg);overflow:visible}
.ctm-ring circle{fill:none;stroke-width:2.6}
.ctm-ring .tr{stroke:var(--dm-rail)}
.ctm-ring .fl{stroke:var(--dm-accent-mark,var(--dm-accent));stroke-linecap:round;stroke-dasharray:0 100;transition:stroke-dasharray .42s var(--dm-ease),stroke .32s}
.ctm.hot .ctm-ring .fl{stroke:var(--dm-warn-mark)}

/* Clean (owner, 17 and 18 Nov): the pill is the flat secondary control (a hairline and a light fill, no press); the ring is
   the accent's mark on a grey rail. The panel is a 22px card with an off-white head strip and foot strip, opening and
   shutting with a fade and no move or blur, its content 16px in from every edge: the legend's rows sit 8px in with 8px of their
   own, their hover concentric with the card's corners, and Compact is a 28px secondary pill 16px from the foot's side, bottom
   and hairline (owner, 23 Nov). The
   parts of the bar keep their colours */
:root[data-style="clean"] .ctm-tg,:root [data-style="clean"] .ctm-tg,:root [data-style="clean"].ctm-tg{height:32px;border-radius:var(--dm-r-pill);color:var(--dm-fg2);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth);transition:box-shadow var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ctm-tg:hover,:root [data-style="clean"] .ctm-tg:hover,:root [data-style="clean"].ctm-tg:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .ctm-tg:active,:root [data-style="clean"] .ctm-tg:active,:root [data-style="clean"].ctm-tg:active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .ctm-ring .tr,:root [data-style="clean"] .ctm-ring .tr,:root [data-style="clean"].ctm-ring .tr{stroke:var(--dm-rail)}
:root[data-style="clean"] .ctm-pop,:root [data-style="clean"] .ctm-pop,:root [data-style="clean"].ctm-pop{padding:0;gap:0;transition:opacity .24s var(--dm-ease),transform .32s var(--dm-ease),height .32s var(--dm-ease),margin-top .32s var(--dm-ease),visibility 0s}
:root[data-style="clean"] .ctm[data-open="0"] .ctm-pop,:root [data-style="clean"] .ctm[data-open="0"] .ctm-pop,:root [data-style="clean"].ctm[data-open="0"] .ctm-pop{transition:opacity .15s var(--dm-ease),transform .2s var(--dm-ease),height .24s var(--dm-ease),margin-top .24s var(--dm-ease),visibility 0s .24s}
:root[data-style="clean"] .ctm-ph,:root [data-style="clean"] .ctm-ph,:root [data-style="clean"].ctm-ph{padding:calc(var(--dm-strip-y) + 5px) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);font-size:12.5px;line-height:18px}
:root[data-style="clean"] .ctm-bar,:root [data-style="clean"] .ctm-bar,:root [data-style="clean"].ctm-bar{margin:16px 16px 0;height:6px;gap:2px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-rail)}
:root[data-style="clean"] .ctm-bar i,:root [data-style="clean"] .ctm-bar i,:root [data-style="clean"].ctm-bar i{transition:width .42s var(--dm-ease),opacity .15s var(--dm-ease)}
:root[data-style="clean"] .ctm-bar i:first-child,:root [data-style="clean"] .ctm-bar i:first-child,:root [data-style="clean"].ctm-bar i:first-child{border-radius:3px 0 0 3px}
:root[data-style="clean"] .ctm-bar.hl i:not(.on),:root [data-style="clean"] .ctm-bar.hl i:not(.on),:root [data-style="clean"].ctm-bar.hl i:not(.on){opacity:.28}
:root[data-style="clean"] .ctm-leg,:root [data-style="clean"] .ctm-leg,:root [data-style="clean"].ctm-leg{margin:8px 8px 0}
:root[data-style="clean"] .ctm-l,:root [data-style="clean"] .ctm-l,:root [data-style="clean"].ctm-l{padding:5px 8px;border-radius:calc(var(--dm-r-card) - 8px);transition:background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ctm-l:hover,:root [data-style="clean"] .ctm-l:hover,:root [data-style="clean"].ctm-l:hover{background:color-mix(in srgb,var(--dm-fg) 5%,transparent)}}
:root[data-style="clean"] .ctm-msg,:root [data-style="clean"] .ctm-msg,:root [data-style="clean"].ctm-msg{margin:0 16px}
:root[data-style="clean"] .ctm-msg.on,:root [data-style="clean"] .ctm-msg.on,:root [data-style="clean"].ctm-msg.on{margin:8px 16px 5px}
:root[data-style="clean"] .ctm-msg.warn>span,:root [data-style="clean"] .ctm-msg.warn>span,:root [data-style="clean"].ctm-msg.warn>span{margin:0 -8px;padding:8px;border-radius:calc(var(--dm-r-card) - 8px)}
:root[data-style="clean"] .ctm-f,:root [data-style="clean"] .ctm-f,:root [data-style="clean"].ctm-f{margin-top:11px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .ctm-go,:root [data-style="clean"] .ctm-go,:root [data-style="clean"].ctm-go{height:28px;padding:0 12px;border-radius:var(--dm-r-pill)}
:root[data-style="clean"] .ctm-go:not(.warn),:root [data-style="clean"] .ctm-go:not(.warn),:root [data-style="clean"].ctm-go:not(.warn){color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ctm-go:not(.warn):hover,:root [data-style="clean"] .ctm-go:not(.warn):hover,:root [data-style="clean"].ctm-go:not(.warn):hover{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .ctm-go:not(.warn):active,:root [data-style="clean"] .ctm-go:not(.warn):active,:root [data-style="clean"].ctm-go:not(.warn):active{box-shadow:var(--dm-btn2-press)}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] :is(.ctm-pop,.ctm-bar i,.ctm-tg),:root [data-style="clean"] :is(.ctm-pop,.ctm-bar i,.ctm-tg),:root [data-style="clean"]:is(.ctm-pop,.ctm-bar i,.ctm-tg){transition:none!important}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, enter, html, swap, tip, tween } from '../core/core.js';
DM.def('context-meter', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d','xs'));
  const LIMIT = 200;
  // what fills the context, in thousands of tokens; each part lists what's in it on hover. The parts take the chart palette's
  // accent, violet and teal; the instructions, the quiet part, a neutral grey that keeps 3:1 (green would be Blueprint's
  // accent again, and orange the warning)
  const P = [
    { k:'files', l:'Files', v:56.2, c:'var(--dm-c1)', tip:'Pricing.fig export 31.9k, PricingCard.tsx 18.2k, tokens.css 6.1k' },
    { k:'tools', l:'Tool output', v:41.8, c:'var(--dm-c2)', tip:'Contrast check 17.4k, Figma frames 15.6k, grid audit 8.8k' },
    { k:'chat', l:'Chat', v:32.1, c:'var(--dm-c6)', tip:'48 turns with Maya Kim since 09:12' },
    { k:'sys', l:'Instructions', v:6.3, c:'var(--dm-muted)', tip:'Studio guidelines 4.1k, pricing brief 2.2k' }
  ];
  const root = $('.ctm', r), tg = $('.ctm-tg', r), pop = $('.ctm-pop', r), arc = $('.ctm-ring .fl', r), pc = $('.ctm-pc', r), tot = $('.ctm-tot', r);
  const bar = $('.ctm-bar', r), leg = $('.ctm-leg', r), msg = $('.ctm-msg', r), go = $('.ctm-go', r), hint = $('.ctm-hint', r);
  bar.innerHTML = P.map(p => `<i data-k="${p.k}" style="--dm-c:${p.c}"></i>`).join('');
  leg.innerHTML = P.map(p => `<div class="ctm-l" data-k="${p.k}" style="--dm-c:${p.c}" data-tip="${p.tip}"><span class="sw"></span>${p.l}<span class="v num">0k</span></div>`).join('');
  const fmt = v => v.toFixed(1) + 'k', sum = () => P.reduce((t, p) => t + p.v, 0);
  // the numbers count to their new values; the bar, the ring and the percentage follow
  const shown = {}; let total = 0;
  function paint(ms = 900){
    const all = sum(), pct = Math.round(all / LIMIT * 100);
    P.forEach(p => { $(`i[data-k="${p.k}"]`, bar).style.width = (p.v / LIMIT * 100) + '%'; const el = $(`.ctm-l[data-k="${p.k}"] .v`, leg), from = shown[p.k] || 0; shown[p.k] = p.v; tween(from, p.v, ms, x => el.textContent = fmt(x)); });
    const from = total; total = all; tween(from, all, ms, x => { tot.textContent = fmt(x); pc.textContent = Math.round(x / LIMIT * 100) + '%'; });
    arc.style.strokeDasharray = pct + ' 100'; root.classList.toggle('hot', pct >= 85); tg.setAttribute('aria-label', `Context, ${pct}% used`);
  }
  // a warning is a warning notice with the filled sign, and Compact, the action that resolves it, takes the warning tint
  const WARN = '<svg class="ctm-wi" viewBox="0 0 24 24" aria-hidden="true"><path class="a" d="M12 3.6 2.6 19.9h18.8z"/><path class="b" d="M12 9.6v4.4M12 17v.01"/></svg>';
  const say = (text, tone) => { msg.className = 'ctm-msg on ' + tone; swap(msg.firstElementChild, `${tone === 'warn' ? WARN : I('ok','xs')}<span>${text}</span>`, true); go.classList.toggle('warn', tone === 'warn'); go.classList.toggle('soft', tone !== 'warn'); };
  const hush = () => { msg.className = 'ctm-msg'; go.classList.remove('warn'); go.classList.add('soft'); };
  // hovering a part lights its share of the bar
  c.on(leg, 'pointerover', e => { const l = e.target.closest('.ctm-l'); if (!l) return; bar.classList.add('hl'); $$('i', bar).forEach(i => i.classList.toggle('on', i.dataset.k === l.dataset.k)); });
  c.on(leg, 'pointerout', e => { if (!leg.contains(e.relatedTarget)) bar.classList.remove('hl'); });
  // the pill opens and shuts the panel; Escape shuts it while the pointer or the focus is on the meter
  const setOpen = (o, back) => { root.dataset.open = o ? '1' : '0'; tg.setAttribute('aria-expanded', o); pop.inert = !o; if (back) tg.focus({ preventScroll:true }); };
  tg.onclick = () => setOpen(root.dataset.open !== '1');
  c.on(document, 'keydown', e => { if (e.key === 'Escape' && root.dataset.open === '1' && (root.contains(document.activeElement) || root.matches(':hover'))) setOpen(false, root.contains(document.activeElement)); });
  // new tool output lands and takes the context close to its limit
  function arrive(){ P[1].v = +(P[1].v + 38.5).toFixed(1); paint(700); say(`${Math.round(sum() / LIMIT * 100)}% full. Older turns start to drop at 200k`, 'warn'); }
  // Compact turns older turns into a summary and trims old tool output; Undo puts them back
  const before = {}; let state = 'full';
  const run = html('<span class="ctm-run" role="status" hidden><span class="spin"></span><span class="shim">Compacting…</span></span>'); go.after(run);
  // the button is as wide as its words and eases to its new width when they change (owner, 18 Nov)
  const label = h => { const w0 = go.getBoundingClientRect().width; go.innerHTML = h; const w1 = go.getBoundingClientRect().width;
    if (!REDUCE && w0 && Math.abs(w1 - w0) > .5) go.animate([{ width:w0 + 'px' }, { width:w1 + 'px' }], { duration:340, easing:'cubic-bezier(.23,1,.32,1)' }); };
  go.onclick = () => c.run(async () => {
    if (go._busy) return; go._busy = true;
    if (state === 'full'){
      P.forEach(p => before[p.k] = p.v); const was = sum();
      const had = document.activeElement === go; go.hidden = true; run.hidden = false;
      swap(hint, '<span class="shim">Summarising 48 turns</span>', true); await c.wait(1000);
      P[2].v = 4.6; P[1].v = +(P[1].v - 13.7).toFixed(1); paint(1100);
      say(`Freed ${fmt(was - sum())} tokens. 9 decisions kept`, 'ok'); swap(hint, 'Older turns are now a summary');
      c.later(REDUCE ? 0 : 170, () => { run.hidden = true; go.innerHTML = 'Undo'; go.hidden = false; enter(go); if (had) go.focus({ preventScroll:true }); }); state = 'compact';
    } else {
      P.forEach(p => p.v = before[p.k]); paint(700); hush(); swap(hint, 'Summarises older turns'); c.later(REDUCE ? 0 : 170, () => label('Compact')); state = 'full';
    }
    go._busy = false;
  });
  // it opens on its real numbers; they only count when something changes
  paint(1);
  // the preview's story: read what fills it, new tool output pushes it close to the limit, compact, then shut it
  if (r === c.st) c.story(async s => {
    await s.beat(3);
    await s.point($('.ctm-l[data-k="tools"]', leg)); await s.beat(3);
    await s.point($('.ctm-l[data-k="files"]', leg)); await s.beat(3);
    s.away(); await s.beat(1);
    arrive(); await s.beat(4);
    await s.tap(go); s.away(); await s.until(() => state === 'compact'); await s.beat(4);
    await s.tap(tg); s.away(); await s.beat(2);
  });
});
